const fs = require('fs');
const path = require('path');

const readme = fs.readFileSync(path.join(__dirname, 'README.md'), 'utf8');
const headings = readme
  .split(/\r?\n/)
  .filter((line) => line.startsWith('#'));

fs.writeFileSync(path.join(__dirname, 'INDEX.md'), headings.join('\n') + '\n');

